const site = depot();
const materials = ["cobblestone", "oak_log", "spruce_log", "birch_log", "cherry_log", "dark_oak_log"];
let block = null;
for (const name of materials) {
  if (inventory_count(name) >= 1) {
    block = name;
    break;
  }
}
if (!block) {
  const took = await take_from_depot(materials);
  if (took.ok) {
    block = took.name;
  }
}
if (!block) {
  return { done: false, detail: 'nothing to build with' };
}
let laid = 0;
for (let i = 2; i < 60 && laid < 4; i++) {
  if (inventory_count(block) < 1) {
    break;
  }
  const x = site.x + i;
  const z = site.z;
  let ground = null;
  for (let y = site.y + 6; y >= site.y - 12; y--) {
    const at = block_at(x, y, z);
    const below = block_at(x, y - 1, z);
    if (at === 'air' && below !== 'air' && below !== null) {
      ground = y;
      break;
    }
  }
  if (ground === null) {
    continue;
  }
  const under = block_at(x, ground - 1, z);
  if (under === 'cobblestone' || (under !== null && under.endsWith('_log'))) {
    continue;
  }
  const put = await place(block, x, ground, z);
  if (put.ok) {
    laid += 1;
  }
}
if (laid < 1) {
  return { done: false, detail: 'the wall could not grow' };
}
return { done: true, detail: 'the wall grew by ' + laid };
